import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Material Design","description":"Material Design 1.1.0 for Studio 0.1.292 with DE/EN/FR and compatible updates.","frontmatter":{"title":"Material Design","description":"Material Design 1.1.0 for Studio 0.1.292 with DE/EN/FR and compatible updates."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/materialdesign.md","filePath":"en/projects/grafik-visual-studio/materialdesign.md","lastUpdated":1793113714000}'),s={name:"en/projects/grafik-visual-studio/materialdesign.md"};function n(o,e,d,l,c,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="material-design" tabindex="-1">Material Design <a class="header-anchor" href="#material-design" aria-label="Permalink to &quot;Material Design&quot;">​</a></h1><p>From <strong>Studio 0.1.295</strong>, package icons and their symbol area fill the sidebar/selector frame. Existing graphics and settings are retained; no package update is required. <a href="/en/projects/grafik-visual-studio/interaktiv">Interactive additions</a>.</p><p><strong>Package 1.1.0 · Studio 0.1.292 or newer · 49 widgets · MIT.</strong> Independent renderers inspired by <a href="https://github.com/typhosj/ioBroker.vis2-materialdesign" target="_blank" rel="noreferrer">ioBroker VIS2 Material Design by typhosj/Scrounger</a>. Original MDI assignments remain local SVGs. Technical package ID: <code>ugso.materialdesign</code>.</p><p><a href="/projects/grafik-visual-studio/materialdesign">Deutsch</a> · <a href="/fr/projects/grafik-visual-studio/materialdesign">Français</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign" target="_blank" rel="noreferrer">Source</a></p><h2 id="installation-and-preserved-settings" tabindex="-1">Installation and preserved settings <a class="header-anchor" href="#installation-and-preserved-settings" aria-label="Permalink to &quot;Installation and preserved settings&quot;">​</a></h2><ol><li>Export the existing Studio project as JSON.</li><li>Update Studio to <strong>0.1.292 or newer</strong> and restart.</li><li><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/dist/ugso.materialdesign-1.1.0.wg" target="_blank" rel="noreferrer">Download Material Design 1.1.0</a>. Install through <strong>Settings → Widget packages → Local</strong>, or use the direct GitHub file URL.</li><li>The package updates additively. Reload the page and check the existing project.</li></ol><p>Installation <strong>never rewrites project files</strong>. Existing fields, defaults, order and technical IDs remain protected. New fields/groups and choices are appended. Colors, text, dimensions, entity assignments and disabled groups stay saved. Older published packages remain available.</p><p>Old <strong>State Multi</strong> widgets retain their value cycle. Multiple-target writing is an explicitly selected mode. Old Advanced Views retain mapped values; page name/ID and numeric index are additional modes. New widgets include the corresponding original modes. Design style changes never alter targets.</p><h2 id="languages-and-appearance" tabindex="-1">Languages and appearance <a class="header-anchor" href="#languages-and-appearance" aria-label="Permalink to &quot;Languages and appearance&quot;">​</a></h2><p><strong>Material language</strong> follows Studio or selects <strong>German, English or French</strong> for the widget and its Material properties. User text, page IDs and entity IDs are never translated. The overall Studio interface remains DE/EN; French is offered for Material here.</p><p><strong>Classic</strong>, <strong>Material 3</strong> and <strong>Project default</strong> remain selectable. Color scheme follows the page or forces Light/Dark. Explicit colors, font sizes and spacing take precedence. The preview retains 26 palettes and the original white Classic background.</p><h2 id="widgets-and-original-style-features" tabindex="-1">Widgets and original-style features <a class="header-anchor" href="#widgets-and-original-style-features" aria-label="Permalink to &quot;Widgets and original-style features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Features and controls</th></tr></thead><tbody><tr><td>Buttons / Icon Buttons</td><td>State labels/colors/icons, pressed color, momentary mode, bounded addition, new window, navigation and timed unlock</td></tr><tr><td>State Multi</td><td>Previous cycle or multiple entities with separate values and delays</td></tr><tr><td>Checkbox / Switch</td><td>Custom ON/OFF or boolean mode, label position and actual switch track/thumb</td></tr><tr><td>Input / Select / Autocomplete</td><td>Input shapes, affixes, hints/counters, icons, hover/selection colors, keyboard and mask: # = digit, A = letter, * = letter/digit</td></tr><tr><td>Slider / Slider Round</td><td>Effective handle/track sizes, limits/step, ticks, working entity, write during interaction or on release, arc/start angle</td></tr><tr><td>Progress</td><td>Linear/circular, determinate/indeterminate, size/rotation, threshold colors and value text</td></tr><tr><td>Value / Icon / Version</td><td>Number/boolean/text/date/duration, factor/offset, conditions, link and change effect; static or state icon; actual package version</td></tr><tr><td>HTML Card</td><td>Title/subtitle, image, card layouts, colors, image refresh and isolated HTML</td></tr><tr><td>List / Icon List / Table / Alerts</td><td>Subtexts, navigation/links/controls, JSON status bars, image columns, column formatting, fixed header, sorting and acknowledgement</td></tr><tr><td>Four charts</td><td>Bars, pie/doughnut, JSON and Recorder; up to four Y axes, stacks, filled/stepped lines, tooltips, labels, palettes and legend positions</td></tr><tr><td>Calendar</td><td>Month/week/day/year/list, week numbers, colors and time grid in DE/EN/FR</td></tr><tr><td>Top App Bar</td><td>Modal/permanent/automatic drawer, child entries and selected index; previous page links remain a separate mode</td></tr><tr><td>Grid/Masonry / Advanced Views</td><td>Responsive columns, per-view visibility, mappings/name/index, boolean indices 0/1, preload and retained child views</td></tr></tbody></table><p><strong>Show advanced options</strong> reveals details without deleting hidden values. Set counts for targets, views, series or menu items.</p><h2 id="home-assistant-and-data" tabindex="-1">Home Assistant and data <a class="header-anchor" href="#home-assistant-and-data" aria-label="Permalink to &quot;Home Assistant and data&quot;">​</a></h2><p>Validated HA actions support <code>switch/input_boolean</code>, <code>number/input_number</code>, <code>text/input_text</code>, <code>select/input_select</code>, <code>button/input_button</code> with <code>PRESS</code>, light brightness, fan percentage and cover position. States, options and ranges are checked. Sensors, attributes and unavailable entities remain displays.</p><p>Multiple-target actions are sequential and stop on errors or page changes. Completed actions are not rolled back. Arbitrary HA services and executable ioBroker bindings are unsupported.</p><p>Top App Bar <strong>State mode</strong> writes its index to its entity. <strong>Advanced View in Widget 8</strong>, sharing that entity and using <strong>Index mode</strong>, displays the corresponding local Studio page. Without an entity, use existing Studio data flow; separate local preview values are not shared automatically.</p><p>Lists read editor rows or JSON; tables use configured column keys. Optional list HTML is sanitized: no scripts, event handlers or active embeds. HTML cards remain sandboxed. External sites may block iframes.</p><p>Charts accept <code>axisLabels/graphs</code>, <code>labels/datasets</code> or point lists. Recorder is limited to <strong>ten entities and 1–168 hours</strong>. The X axis respects actual time spacing. Aggregation: none, average, minimum, maximum, sum or last value, with a minute interval. Missing states are not invented.</p><p>No automatic ioBroker project import: HA entities, Recorder and Studio pages replace object IDs, history adapters and VIS views. SVG charts and renderers are independent implementations; universal pixel identity is not claimed.</p><h2 id="checks-and-publishing" tabindex="-1">Checks and publishing <a class="header-anchor" href="#checks-and-publishing" aria-label="Permalink to &quot;Checks and publishing&quot;">​</a></h2><p>Browser checks cover all 49 entries in DE/EN/FR, Classic/Material 3 and Light/Dark plus interaction. Real package upgrades retain old project files byte-identically. Check actual HA device functions in your own installation.</p><p><a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/materialdesign-widgetvergleich.json" target="_blank" rel="noreferrer">Comparison project</a> · <a href="https://github.com/rockbaer2007/ha-grafik-visual-studio-materialdesign/blob/main/comparison/AUDIT-2026-10-12.md" target="_blank" rel="noreferrer">Initial audit</a></p><p>Register <strong>1.1.0</strong>, minimum Studio <strong>0.1.292</strong>, ID <code>ugso.materialdesign</code> and MIT in the <a href="https://visualstudio.ugso-software.de/?lang=en" target="_blank" rel="noreferrer">package catalog</a>. Publishing to GitHub does not automatically approve a catalog entry. Checksum: <code>dist/SHA256SUMS</code>.</p>',25)])])}const h=t(s,[["render",n]]);export{u as __pageData,h as default};
